# Get top runs by mae_surf_p (aggregated across splits)
runs = api.runs("wandb-applied-ai-team/kagent-v1", filters={"state": "finished"}, order="+summary_metrics.val/loss", per_page=30)
results = []
for r in runs:
    try:
        maes = []
        for split in ["val_in_dist", "val_tandem_transfer", "val_ood_cond", "val_ood_re"]:
            p = r.summary.get(f"best_best_{split}/mae_surf_p", r.summary.get(f"best_{split}/mae_surf_p", None))
            if p is not None:
                maes.append(p)
        if len(maes) == 4:
            avg = sum(maes) / 4
            results.append((avg, r.name, maes))
    except:
        pass

results.sort()
print("Top runs by avg mae_surf_p across val splits:")
for avg, name, maes in results[:15]:
